    {
      "claim": "The query is a large macrocyclic peptidomimetic with molecular weight 757, TPSA 180.5, and full ionization at physiological pH, which aligns with the low oral bioavailability direction of the closest transferable contexts.",
      "card_ids": ["C01","C05","C09","C10","C16","C04","C12"]
    },
    {
      "claim": "Animal high bioavailability records such as retosiban rat about 100 percent, ER-30346 dog and rat 74 and 48 percent, UK-427857 dog about 40 percent, and DORA-15 moderate exposure are species specific and do not override human low bioavailability measurements.",
      "card_ids": ["C31","C19","C30","C21","C28","C29"]
    },
    {
      "claim": "Retosiban human bioavailability of 17 to 25 percent is borderline and does not affirmatively establish F at or above 20 percent because it includes extensive first-pass elimination.",
      "card_ids": ["C15"]
    },
    {
      "claim": "The L3 oral exposure records for naltrexone, treprostinil, and dihydroergotamine metabolite provide Cmax and AUC values but no bioavailability fraction and no structural relation to the query.",
      "card_ids": ["C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42","C43"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42","C43"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is supplied.",
    "No matched oral versus intravenous exposure data for the query are available.",
    "No query-specific absorption, permeability, metabolism, or formulation data are supplied.",
    "L3 oral exposure records are for unrelated small molecules and do not inform the query threshold.",
    "Animal high bioavailability records are species specific and not directly transferable to humans."
  ],
  "decision_summary": "Predicted low remains supported by multiple transferable human absolute or relative bioavailability records below 20 percent for large peptidomimetic and macrocyclic agents. The L3 oral exposure records for naltrexone, treprostinil, and dihydroergotamine metabolite do not measure bioavailability and are not structurally relevant to the query, so they do not change the decision. Confidence stays moderate because no direct query bioavailability measurement is available."
}

